      "keystrokes": "cat <<'EOF' > /root/output/js/visualization.js
// Load data
d3.csv("data/stock-descriptions.csv").then(data => {
    // Process data
    data.forEach(d => {
        d.marketCapRaw = d.marketCap;
        d.marketCap = d.marketCap ? +d.marketCap : 0;
        d.isETF = d.marketCap === 0;
    });

    const width = 800;
    const height = 800;
    const svg = d3.select("#chart-area")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .attr("viewBox", [0, 0, width, height]);

    // 1. Bubbles sized by market capitalization
    // ETFs sized uniformly (let's say equivalent to a small cap or fixed radius)
    const marketCaps = data.filter(d => !d.isETF).map(d => d.marketCap);
    const minCap = d3.min(marketCaps);
    const maxCap = d3.max(marketCaps);

    const sizeScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([15, 60]); // Adjust range as needed

    const getRadius = (d) => d.isETF ? 15 : sizeScale(d.marketCap);

    // 2. Colored by sector
    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    // 3. Force simulation for clusters by sector
    // Calculate centers for each sector
    const sectorCenters = {};
    const numSectors = sectors.length;
    // Arrange centers in a circle or grid. Let's do a circle.
    const radius = 250;
    sectors.forEach((sector, i) => {
        const angle = (i / numSectors) * 2 * Math.PI;
        sectorCenters[sector] = {
            x: width / 2 + radius * Math.cos(angle),
            y: height / 2 + radius * Math.sin(angle)
        };
    });

    const simulation = d3.forceSimulation(data)
        .force("charge", d3.forceManyBody().strength(-5))
        .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
        .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
        .force("collide", d3.forceCollide(d => getRadius(d) + 2).iterations(4));

    // Draw bubbles
    const bubbles = svg.append("g")
        .selectAll("circle")
        .data(data)
        .join("circle")
        .attr("r", d => getRadius(d))
        .attr("fill", d => colorScale(d.sector))
        .attr("id", d => "bubble-" + d.ticker);

    // 5. Labels
    const labels = svg.append("g")
        .selectAll("text")
        .data(data)
        .join("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .style("font-size", d => Math.min(12, getRadius(d)/2) + "px"); // Scale text slightly

    simulation.on("tick", () => {
        bubbles
            .attr("cx", d => d.x)
            .attr("cy", d => d.y);
        labels
            .attr("x", d => d.x)
            .attr("y", d => d.y + 3); // approximate vertical centering
    });

    // Legends
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", "translate(20, 20)");

    sectors.forEach((sector, i) => {
        const g = legend.append("g")
            .attr("transform", `translate(0, ${i * 20})`);

        g.append("rect")
            .attr("width", 15)
            .attr("height", 15)
            .attr("fill", colorScale(sector));

        g.append("text")
            .attr("x", 20)
            .attr("y", 12)
            .text(sector);
    });

    // 6. Tooltip
    const tooltip = d3.select("#tooltip");
    bubbles.on("mouseover", (event, d) => {
        if (d.isETF) return;
        tooltip.style("opacity", 1)
            .html(`<strong>${d.ticker}</strong><br>${d["full name"]}<br>${d.sector}`)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
    }).on("mouseout", () => {
        tooltip.style("opacity", 0);
    });

    // Data Table
    const table = d3.select("#table-area").append("table");
    const thead = table.append("thead");
    const tbody = table.append("tbody");

    const columns = ["Ticker symbol", "Full company name", "Sector", "Market cap"];
    thead.append("tr")
        .selectAll("th")
        .data(columns)
        .join("th")
        .text(d => d);

    // Format market cap helper
    const formatMarketCap = (val) => {
        if (!val) return "N/A";
        const format = d3.format(".2s");
        return format(val).replace("G", "B"); // d3 uses G for Giga, usually Billions in finance
    };

    const rows = tbody.selectAll("tr")
        .data(data)
        .join("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", (event, d) => highlight(d));

    rows.selectAll("td")
        .data(d => [
            d.ticker,
            d["full name"],
            d.sector,
            d.isETF ? "N/A" : formatMarketCap(d.marketCap)
        ])
        .join("td")
        .text(d => d);

    // Interaction: Highlight
    bubbles.on("click", (event, d) => highlight(d));

    function highlight(d) {
        // Reset
        bubbles.classed("highlighted", false);
        rows.classed("highlighted", false);

        // Highlight selected
        d3.select("#bubble-" + d.ticker).classed("highlighted", true);
        const row = d3.select("#row-" + d.ticker);
        row.classed("highlighted", true);

        // Scroll table to row
        row.node().scrollIntoView({ behavior: "smooth", block: "center" });
    }
});
